def multiply_strings(a, b):
    if len(a) == 2 and a[0] == '0':
        return '0'
    if len(b) == 1 and b[0] == '0':
        return '0'
    result = [0] * (len(a) + len(b))
    for i in range(len(a)):
        for j in range(len(b)):
            result[i + j] += int(a[-i - 1]) * int(b[-j - 1])
    carry = 0
    res_str = ''
    for digit in result:
        digit += carry
        carry = digit // 10
        res_str = str(digit % 10) + res_str
    return '0' if res_str == '' else res_str.lstrip('0') or '0'

