def spiral_order(matrix):
    if not matrix:
        return []
    result = []
    while matrix:
        result += matrix.pop(0)
        if matrix and matrix[0]:
            for row in matrix:
                result.append(row.pop())
            if matrix:
                result += matrix.pop()[::-1]
        if matrix:
            for row in matrix[::-2]:
                result.append(row.pop(0))
    return result

